insert into parties (id, name, short_name, orientation, color) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:party:lo'), 'Lutte Ouvrière', 'LO', 'extreme-gauche', '#a3123a') on conflict (id) do nothing;
insert into parties (id, name, short_name, orientation, color) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:party:dlf'), 'Debout la France', 'DLF', 'droite', '#1e3a5f') on conflict (id) do nothing;
insert into candidates (id, slug, name, photo_url, party_id, biography, official_website, election_id, is_demo, order_index) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:fabien-roussel'), 'fabien-roussel', 'Fabien Roussel', '/candidates/fabien-roussel.jpg', uuid_generate_v5(uuid_ns_url(), 'poliscope:party:pcf'), 'Né le 16 avril 1969 à Béthune, Fabien Roussel a d''abord été journaliste avant de devenir secrétaire national du Parti communiste français depuis novembre 2018. Ancien député du Nord (2017-2024), il est maire de Saint-Amand-les-Eaux depuis janvier 2025. Candidat à la présidentielle en 2022 (2,28 %, 8e place), il se représente en 2027.', 'http://www.fabienroussel2027.fr/', uuid_generate_v5(uuid_ns_url(), 'poliscope:election:presidentielle-2027'), false, 11) on conflict (id) do nothing;
insert into candidates (id, slug, name, photo_url, party_id, biography, official_website, election_id, is_demo, order_index) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nathalie-arthaud'), 'nathalie-arthaud', 'Nathalie Arthaud', '/candidates/nathalie-arthaud.jpg', uuid_generate_v5(uuid_ns_url(), 'poliscope:party:lo'), 'Née le 23 février 1970 à Peyrins (Drôme), Nathalie Arthaud est professeure agrégée d''économie-gestion. Porte-parole de Lutte Ouvrière depuis décembre 2008, elle a succédé à Arlette Laguiller comme visage du parti. Candidate à la présidentielle en 2012, 2017 et 2022 (autour de 0,6 % à chaque fois), elle se présente pour la quatrième fois en 2027.', 'https://www.lutte-ouvriere.org/', uuid_generate_v5(uuid_ns_url(), 'poliscope:election:presidentielle-2027'), false, 12) on conflict (id) do nothing;
insert into candidates (id, slug, name, photo_url, party_id, biography, official_website, election_id, is_demo, order_index) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nicolas-dupont-aignan'), 'nicolas-dupont-aignan', 'Nicolas Dupont-Aignan', '/candidates/nicolas-dupont-aignan.jpg', uuid_generate_v5(uuid_ns_url(), 'poliscope:party:dlf'), 'Né le 7 mars 1961 à Paris, Nicolas Dupont-Aignan est diplômé de Sciences Po Paris et de l''ENA. Ancien membre du RPR puis de l''UMP, il fonde Debout la France en 2008, qu''il préside depuis. Maire de Yerres (1995-2017, puis à nouveau depuis 2020) et ancien député de l''Essonne (1997-2024), il a été candidat à la présidentielle en 2012, 2017 (4,7 %) et 2022, et se présente pour la cinquième fois en 2027.', 'https://www.debout-la-france.fr/', uuid_generate_v5(uuid_ns_url(), 'poliscope:election:presidentielle-2027'), false, 13) on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-72'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:fabien-roussel'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:retraites'), 'Retour de l''âge légal de départ à 60 ans', 'Rétablir la retraite à 60 ans, financée par la taxation des revenus financiers et la lutte contre le chômage.', 'Le PCF propose de rétablir l''âge de départ à la retraite à 60 ans, en finançant la réforme par une taxation des revenus financiers et une baisse du chômage plutôt que par un allongement de la durée de cotisation.', 'Parti communiste français (pcf.fr)', 'https://www.pcf.fr/retraites_pour_une_r_forme_digne_des_jours_heureux', '2026-09-06', '2026-09-03', 'programme', 'Âge légal') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-73'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:fabien-roussel'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:pouvoir-achat'), 'SMIC à 1 500 euros net et semaine de 32 heures', 'Porter le SMIC à 1 500 euros net, instaurer la semaine de 32 heures sans perte de salaire et revaloriser les petites retraites à 1 200 euros net.', 'Ce socle social, présenté sous le slogan « la France de la feuille de paie », prévoit une hausse du SMIC à 1 500 euros nets par mois, le passage à une semaine de travail de 32 heures sans baisse de rémunération, et une revalorisation des petites pensions à 1 200 euros net.', 'Europe 1', 'https://www.europe1.fr/politique/a-marseille-fabien-roussel-prone-la-france-de-la-feuille-de-paie-4092220', '2022-02-06', '2026-09-03', 'programme', 'SMIC, Temps de travail') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-74'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:fabien-roussel'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:international'), 'Sortie du commandement militaire intégré de l''OTAN', 'Sortir la France du commandement militaire intégré de l''OTAN et proposer une conférence de sécurité collective en Europe.', 'Dans son rapport introductif au Conseil national du PCF, Fabien Roussel réaffirme que « la France ne peut plus, ne doit plus participer à l''OTAN, dans son commandement militaire », au profit d''une architecture de sécurité collective européenne fondée sur la coopération entre les peuples.', 'Parti communiste français (pcf.fr)', 'https://www.pcf.fr/rapport_introductif_de_fabien_roussel_au_cn_du_10_01_2026', '2026-01-10', '2026-09-03', 'annonce', 'OTAN, Souveraineté') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-75'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:fabien-roussel'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:immigration'), 'Un débat sans tabou sur l''immigration à gauche', 'Appelle le PCF et la gauche à débattre ouvertement de la question migratoire plutôt que de l''éviter.', 'Invité de BFM TV, Fabien Roussel affirme qu''« il faut savoir parler de l''immigration » et que « la question de l''immigration, elle est posée, nous devons savoir en parler », sans se prononcer sur un chiffrage précis du niveau souhaité.', 'Actu Orange (BFM TV)', 'https://actu.orange.fr/videos/politique/pour-fabien-roussel-secretaire-national-du-pcf-il-faut-savoir-parler-de-l-immigration-CNT000002pXlUQ.html', '2026-06-14', '2026-09-03', 'annonce', 'Débat public') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-76'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:fabien-roussel'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:education'), 'Revenu étudiant à 850 euros et repas à 1 euro dans les cantines', 'Créer un revenu étudiant à partir de 850 euros par mois et généraliser le repas à 1 euro dans les cantines scolaires.', 'Le programme du PCF prévoit un revenu étudiant à partir de 850 euros par mois pour financer les études, et la généralisation du repas à 1 euro dans toutes les cantines scolaires.', 'Parti communiste français (pcf.fr)', 'https://www.pcf.fr/le_programme', '2026-09-06', '2026-09-03', 'programme', 'Revenu étudiant, Cantines') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-77'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:fabien-roussel'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:energie'), 'Un mix énergétique nucléaire et renouvelable', 'Défend un mix électrique combinant nucléaire et énergies renouvelables plutôt qu''une sortie du nucléaire.', 'Le programme du PCF défend explicitement « un mix énergétique nucléaire et renouvelable », une position qui distingue le parti d''autres forces de gauche favorables à une sortie du nucléaire.', 'Parti communiste français (pcf.fr)', 'https://www.pcf.fr/le_programme', '2026-09-06', '2026-09-03', 'programme', 'Nucléaire, Renouvelables') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-78'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nathalie-arthaud'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:pouvoir-achat'), 'Échelle mobile des salaires et des pensions', 'Indexer automatiquement les salaires et les pensions sur les prix, sous le contrôle des travailleurs eux-mêmes.', 'Lutte Ouvrière défend l''imposition d''une « échelle mobile des salaires et des pensions établie sous [le] propre contrôle » des travailleurs, pour empêcher que l''inflation n''appauvrisse mécaniquement les salariés et les retraités.', 'Lutte Ouvrière (lutte-ouvriere.org)', 'https://www.lutte-ouvriere.org/journal/article/2018-10-31-face-linflation-echelle-mobile_114571.html', '2018-10-31', '2026-09-03', 'programme', 'Salaires, Pensions') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-79'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nathalie-arthaud'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:economie'), 'Interdiction des licenciements sous peine de réquisition', 'Interdire les licenciements et réquisitionner les entreprises qui y procéderaient malgré tout.', 'Dans un éditorial signé par Nathalie Arthaud, Lutte Ouvrière défend l''« interdiction des licenciements sous peine de réquisition » comme réponse immédiate aux suppressions d''emplois annoncées par les grandes entreprises.', 'Lutte Ouvrière (lutte-ouvriere.org)', 'https://www.lutte-ouvriere.org/portail/editoriaux/interdiction-licenciements-sous-peine-requisition-184019.html', '2025-05-05', '2026-09-03', 'programme', 'Licenciements, Emploi') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-80'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nathalie-arthaud'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:economie'), 'Expropriation des banques et fusion en une seule entité contrôlée par la population', 'Exproprier les banques sans indemnité et les regrouper en une seule entité sous contrôle de la population.', 'Lutte Ouvrière propose d''exproprier les banques sans indemnité ni rachat et de les fusionner en une seule entité, placée sous le contrôle des travailleurs, des petits usagers et de la population, plutôt que sous celui des financiers.', 'Lutte Ouvrière (lutte-ouvriere.org)', 'https://www.lutte-ouvriere.org/journal/article/2008-10-10-moraliser-la-finance-commencerait-par-lexpropriation-des-responsables-de-la-crise_18488.html', '2008-10-10', '2026-09-03', 'programme', 'Banques') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-81'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nathalie-arthaud'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:immigration'), 'Liberté de circulation et d''installation pour tous les travailleurs', 'Défend la liberté de circulation et d''installation pour tous les travailleurs, quelle que soit leur nationalité.', 'Nathalie Arthaud affirme : « Nous sommes pour la liberté de circulation et d''installation de tous les travailleurs et donc pour la liberté des migrants de s''installer où ils le souhaitent », rejetant toute logique de quotas ou de fermeture des frontières au nom de la solidarité de classe entre travailleurs.', 'Breizh-info', 'https://www.breizh-info.com/2019/03/18/114345/nathalie-arthaud-lutte-ouvriere-travailleurs/', '2019-03-18', '2026-09-03', 'precision_ulterieure', 'Liberté de circulation') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-82'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nicolas-dupont-aignan'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:retraites'), 'Référendum pour maintenir la retraite à 62 ans', 'Propose un référendum d''initiative partagée pour maintenir l''âge légal de départ à 62 ans plutôt que de le reporter à 64 ans.', 'En janvier 2023, Nicolas Dupont-Aignan lance une procédure de référendum d''initiative partagée « pour ou contre le maintien de la retraite à 62 ans », qualifiant la réforme du gouvernement de réforme « abominable, inutile et injuste », en cherchant les 185 parlementaires nécessaires pour l''enclencher.', 'Public Sénat', 'https://www.publicsenat.fr/actualites/politique/retraites-une-reforme-abominable-inutile-et-injuste-pour-nicolas-dupont-aignan', '2023-01-16', '2026-09-03', 'annonce', 'Âge légal, Référendum') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-83'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nicolas-dupont-aignan'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:immigration'), 'Rétablir les frontières nationales et sortir de l''espace Schengen', 'Sortir de l''espace Schengen pour rétablir un contrôle national des frontières.', 'Premier des « 10 points du projet européen » de Debout la France : « Rétablir nos frontières nationales et sortir de l''espace Schengen », présenté comme préalable à toute politique migratoire nationale reprise en main.', 'Debout la France (debout-la-france.fr)', 'https://www.debout-la-france.fr/actualite/discours-de-rentree-les-10-points-du-projet-europeen-pour-une-france-libre-au-service-dun-monde-libre/', '2023-09-22', '2026-09-03', 'programme', 'Schengen, Frontières') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-84'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nicolas-dupont-aignan'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:europe'), 'Supprimer la Commission européenne et la Cour de justice de l''UE', 'Supprimer la Commission européenne et la CJUE, affirmer la primauté du droit français et réduire la contribution nette à l''UE à 1 milliard d''euros.', 'Le « projet européen » de Debout la France prévoit de « supprimer la Commission européenne », de « supprimer la Cour de Justice européenne », d''« affirmer la primauté du droit français sur le droit européen », et de « supprimer la contribution annuelle nette de la France de 10 milliards [d''euros] » pour n''en conserver qu''un, dédié aux coopérations volontaires.', 'Debout la France (debout-la-france.fr)', 'https://www.debout-la-france.fr/actualite/discours-de-rentree-les-10-points-du-projet-europeen-pour-une-france-libre-au-service-dun-monde-libre/', '2023-09-22', '2026-09-03', 'programme', 'Institutions européennes, Contribution UE') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-85'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nicolas-dupont-aignan'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:international'), 'Sortir du commandement militaire intégré de l''OTAN', 'Renouer avec une politique étrangère indépendante en sortant du commandement militaire intégré de l''OTAN.', 'Reprenant la doctrine gaulliste, Debout la France propose de « renouer avec une politique étrangère indépendante et sortir du commandement militaire intégré de l''OTAN », sans quitter l''Alliance atlantique elle-même.', 'Debout la France (debout-la-france.fr)', 'https://www.debout-la-france.fr/actualite/discours-de-rentree-les-10-points-du-projet-europeen-pour-une-france-libre-au-service-dun-monde-libre/', '2023-09-22', '2026-09-03', 'programme', 'OTAN, Souveraineté') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-86'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nicolas-dupont-aignan'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:energie'), 'Maintenir le nucléaire et relancer une filière thorium', 'Maintenir le parc nucléaire et développer une filière thorium sur 25 à 30 ans en remplacement progressif de l''uranium.', 'Nicolas Dupont-Aignan défend le maintien du nucléaire dans le mix électrique et propose de « développer des réacteurs fonctionnant au thorium » pour succéder aux centrales à uranium, un combustible présenté comme plus sûr et générant des déchets radioactifs à durée de vie bien plus courte.', 'Techniques de l''Ingénieur', 'https://www.techniques-ingenieur.fr/actualite/articles/marine-pen-nicolas-dupont-aignan-42555/', '2017-04-20', '2026-09-03', 'precision_ulterieure', 'Nucléaire, Thorium') on conflict (id) do nothing;
